import type * as React from 'react';
import type { DOMProps, QAProps } from "../types.js";
export type InputControlView = 'normal' | 'clear';
export type InputControlSize = 's' | 'm' | 'l' | 'xl';
export type InputControlPin = 'round-round' | 'brick-brick' | 'clear-clear' | 'round-brick' | 'brick-round' | 'round-clear' | 'clear-round' | 'brick-clear' | 'clear-brick';
export type InputControlState = 'error';
export type BaseInputControlProps<T = Element> = DOMProps & QAProps & {
    /** The control's `autocomplete` attribute */
    autoComplete?: boolean | 'on' | 'off' | string;
    /** The control's `autofocus` attribute */
    autoFocus?: boolean;
    /** React ref provided to the control */
    controlRef?: React.Ref<T>;
    /** The control's default value. Use when the component is not controlled */
    defaultValue?: string;
    /** Indicates that the user cannot interact with the control */
    disabled?: boolean;
    /** Determines content of the error message */
    errorMessage?: React.ReactNode;
    /** Determines whether the error message will be placed under the input field as text or in the tooltip */
    errorPlacement?: 'outside' | 'inside';
    /** Describes the validation state */
    validationState?: 'invalid';
    /** Shows icon for clearing control's value */
    hasClear?: boolean;
    /** The control's `id` attribute */
    id?: string;
    /** The control's `name` attribute. Will be autogenerated if not specified */
    name?: string;
    /** Fires when the control lost focus. Provides focus event as an callback's argument */
    onBlur?: React.FocusEventHandler<T>;
    /** Fires when the input’s value is changed by the user. Provides change event as an callback's argument */
    onChange?: React.ChangeEventHandler<T>;
    /** Fires when the control gets focus. Provides focus event as an callback's argument */
    onFocus?: React.FocusEventHandler<T>;
    /** Fires when a key is pressed. Provides keyboard event as an callback's argument */
    onKeyDown?: React.KeyboardEventHandler<T>;
    /** Fires when a key is released. Provides keyboard event as an callback's argument */
    onKeyUp?: React.KeyboardEventHandler<T>;
    /** Fires when the input’s value is changed by the user. Provides new value as an callback's argument */
    onUpdate?: (value: string) => void;
    /** The control's border view. `'round-round'` by default */
    pin?: InputControlPin;
    /** Text that appears in the control when it has no value set */
    placeholder?: string;
    /** Indicates that the user cannot change control's value */
    readOnly?: boolean;
    /** The control's size. `'m'` by default */
    size?: InputControlSize;
    /** The control's `tabindex` attribute */
    tabIndex?: number;
    /** The control's value */
    value?: string;
    /** The control's view. `'normal'` by default */
    view?: InputControlView;
};

--- theming scope ---
6-
7-Everything is driven by CSS custom properties prefixed with `--g-*`. There is no runtime styling API you need to call — you set variables and components pick them up.
8-
9-```tsx
10:import {Provider, Button} from '@gravity-ui/uikit';
11-import '@gravity-ui/uikit/styles/fonts.css';
12-import '@gravity-ui/uikit/styles/styles.css';
13-
14-export const App = () => (
15:  <Provider theme="system">
16-    <Button view="action">Branded button</Button>
17:  </Provider>
18-);
19-```
20-
21-## How theming works
22-
23:All variables live on the root class `.g-root`, which `ThemeProvider` assigns to `<body>` by
24:default when used without a parent theme (use `scoped` for a local root). Color variables additionally live on a
25-per-theme class `.g-root_theme_{themeName}`, so switching the theme swaps one set of values for
26-another.
27-
28-```
--
44-| `dark`     | Default dark theme                   |
45-| `light-hc` | Light, high-contrast (accessibility) |
46-| `dark-hc`  | Dark, high-contrast (accessibility)  |
47-
48:Select the application theme via `Provider`:
49-
50-```tsx
51:<Provider theme="dark">{...}</Provider>
52-```
53-
54:The default is `"system"`, which follows the OS color-scheme preference and resolves to `light`
55:or `dark`. You can control what `system` resolves to with `systemLightTheme` / `systemDarkTheme`.
56-Read the requested/resolved theme with `useTheme` / `useThemeValue`; switch it by updating the `theme` prop.
57-
58:## Providers
59-
60:`Provider` is the application provider. Nested Providers are always scoped, even with
61:`scoped={false}`, and inherit unspecified theme, language, layout, and component-default settings.
62-Mobile settings use independent defaults. Use a feature provider to configure just one feature. All listed components and prop types are exported from `@gravity-ui/uikit`.
63-
64:### Provider
65-
66:`ProviderProps` combines the theme props below, `lang` and `fallbackLang`, the mobile props below,
67-`children`, and these settings:
68-
69-| Prop           | Type                                    | Behavior                                                   |
70-| -------------- | --------------------------------------- | ---------------------------------------------------------- |
71:| `layout`       | `Omit<LayoutProviderProps, 'children'>` | Layout configuration and media queries                     |
72-| `defaultProps` | `DefaultPropsMap`                       | Component defaults; explicit component props take priority |
73-
74:It composes `LayoutProvider`, `DefaultPropsProvider`, `ThemeProvider`, `LangProvider`, and
75:`MobileProvider`, and installs a private shared tooltip delay group. Configure that group with
76:`defaultProps={{TooltipDelayGroup: {skipDelay: 500}}}`. Nested Providers and theme scopes share the same group.
77-
78:### ThemeProvider
79-
80:`ThemeProviderProps` accepts `children` and these optional props:
81-
82-| Prop               | Type        | Default without a parent theme              |
83-| ------------------ | ----------- | ------------------------------------------- |
84:| `theme`            | `Theme`     | `system`                                    |
85:| `systemLightTheme` | `RealTheme` | `light`                                     |
86:| `systemDarkTheme`  | `RealTheme` | `dark`                                      |
87-| `direction`        | `Direction` | `ltr`                                       |
88:| `scoped`           | `boolean`   | `false`; always `true` inside another theme |
89:| `rootClassName`    | `string`    | Empty; added to body or the scoped wrapper  |
90-
91:Read the requested theme with `useTheme`, the resolved theme with `useThemeValue`, system mappings
92-with `useThemeSettings`, and direction with `useDirection`. Change theme by updating the provider's
93:`theme` prop. See [Scoped themes](#scoped-themes) for local overrides.
94-
95:### LangProvider
96-
97:`LangProviderProps` accepts `children`, `lang`, and `fallbackLang`. Language names support built-in
98-`en` and `ru` as well as custom languages registered through the i18n API. Nested providers inherit
99-unspecified options. When either language option is specified without a parent language context,
100-the remaining option defaults to `en`. With neither option, the provider passes through the parent
101-context, or `useLang` reads the global `configure` settings when there is no parent context.
102-
103-```tsx
104:<LangProvider lang="ru" fallbackLang="en">
105-  <LocalizedContent />
106:</LangProvider>
107-```
108-
109:### LayoutProvider
110-
111:`LayoutProviderProps` accepts `children`, `config` (partial `LayoutTheme`), and `initialMediaQuery`
112-(a breakpoint name for the initial/SSR render). Nested providers inherit the theme and active
113-breakpoint, including the parent's initial breakpoint during SSR. `config` merges with the parent
